mapper.select:
select COUNT(1) as totalCount, COUNT(case when sur.auth_status = 1 then 1 end ) as verifyedCount, COUNT(case when sur.auth_status = 0 then 1 end ) as verifyCount from sys_user su left join ums_realname_auth sur on sur.user_id = su.id WHERE 1=1 and su.user_identity=3
and su.create_time >= #{startTime}
and su.create_time < #{endTime}

select
COUNT(1) as totalCount,
COUNT(case when auth_status = 0 then 1 end ) as waitVerifyCount,
COUNT(case when auth_status = 1 then 1 end ) as verifyedCount
from job_company
WHERE 1=1

    and create_time >= #{startTime}


    and create_time < #{endTime}


    and auth_status = #{authStatus}

select
COUNT(1) as totalCount,
COUNT(case when post_status = 2 then 1 end ) as openCount,
COUNT(case when post_status != 2 then 1 end ) as noOpenCount
from job_post
WHERE 1=1

    and create_time >= #{startTime}


    and create_time < #{endTime}


    and post_status < #{postStatus}

select
COUNT(1) as totalCount,
COUNT(case when order_status = 2 then 1 end ) as openCount,
COUNT(case when order_status != 2 then 1 end ) as noOpenCount
from job_order
WHERE 1=1

    and create_time >= #{startTime}


    and create_time < #{endTime}


    and order_status < #{orderStatus}
